 const ry=dy*cp-dz*sp,rz=dy*sp+dz*cp,cy=Math.cos(yaw),sy=Math.sin(yaw),rx=dx*cy-rz*sy,zz=dx*sy+rz*cy,len=Math.hypot(rx,ry,zz);
