 const pointers=new Map();let gesture=null,resizeObserver=null,intersectionObserver=null,visible=true;
 const fields=Object.fromEntries(['equipment-title','equipment-body','equipment-check','result','detail','status','credit','history'].map(name=>[name,root.querySelector('[data-scene-'+name+']')]));
 const source=resolveScenePhoto(course,options.photos||[],options.scenePhotos),photo=viewport.querySelector('img');
 if(source){const p=source.photo,path=localUrl(p.path);photo.src=path;photo.alt=title(p,en);photo.loading='lazy';photo.decoding='async';photo.hidden=false;fields.credit.innerHTML=`<strong>${esc(title(p,en))}</strong> · ${esc(p.attribution||p.author||'')} · <a href="${esc(externalUrl(p.licenseUrl))}" target="_blank" rel="noopener noreferrer">${esc(p.license||'')}</a> · <a href="${esc(externalUrl(p.sourceUrl))}" target="_blank" rel="noopener noreferrer">${t('原始照片','Original photograph')} ↗</a><br><span>${source.match==='exact'?t('本工程照片','Photograph of this project'):t('代表性場景','Representative scene')} — ${esc(en?source.noteEn:source.note)}</span>`;
  on(photo,'error',()=>{photo.hidden=true;state.photoReady=false;fields.credit.append(document.createTextNode(t(' · 照片載入失敗，保留原創模型。',' · Photo unavailable; original model remains available.')));requestDraw();});on(photo,'load',()=>{state.photoReady=true;requestDraw();});
 }else fields.credit.textContent=t('尚無適合本領域的已授權照片；顯示原創教學設備。','No suitable licensed photograph is available for this field; original teaching equipment is shown.');
 const architecture=projectArchitecture(course),map=root.querySelector('.iv16-project-map');let selectedNode=null;
 function drawArchitecture(){
  if(!map||!architecture||!map.open)return;const region=map.querySelector('.iv16-architecture'),svg=region.querySelector('svg'),rect=region.getBoundingClientRect();if(rect.width<=0)return;
  svg.setAttribute('viewBox',`0 0 ${rect.width} ${rect.height}`);svg.setAttribute('width',String(rect.width));svg.setAttribute('height',String(rect.height));
  const buttons=new Map([...map.querySelectorAll('[data-scene-node]')].map(b=>[b.dataset.sceneNode,b]));
  svg.innerHTML=architecture.edges.map(edge=>{const a=buttons.get(edge.from)?.getBoundingClientRect(),b=buttons.get(edge.to)?.getBoundingClientRect();if(!a||!b)return '';const x1=a.left-rect.left+a.width/2,y1=a.top-rect.top+a.height/2,x2=b.left-rect.left+b.width/2,y2=b.top-rect.top+b.height/2,dx=x2-x1,dy=y2-y1,length=Math.hypot(dx,dy);if(length<1)return '';const t1=Math.min(a.width/2/Math.max(Math.abs(dx),1e-8),a.height/2/Math.max(Math.abs(dy),1e-8)),t2=Math.min(b.width/2/Math.max(Math.abs(dx),1e-8),b.height/2/Math.max(Math.abs(dy),1e-8)),start=[x1+dx*t1,y1+dy*t1],end=[x2-dx*t2,y2-dy*t2],ux=dx/length,uy=dy/length,active=edge.from===selectedNode||edge.to===selectedNode,colour=active?'#b97a34':'#b0c7bd';return `<path d="M${start[0]},${start[1]} L${end[0]},${end[1]}" stroke="${colour}" stroke-width="${active?2.5:1.5}" fill="none"/><path d="M${end[0]},${end[1]} L${end[0]-ux*8-uy*4},${end[1]-uy*8+ux*4} L${end[0]-ux*8+uy*4},${end[1]-uy*8-ux*4} Z" fill="${colour}"/>`;}).join('');
 }
 function selectProjectNode(id){
  const node=architecture?.nodes.find(n=>n.id===id);if(!node||!map)return;selectedNode=id;
  map.querySelectorAll('[data-scene-node]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sceneNode===id)));
  map.querySelector('[data-scene-node-title]').textContent=title(node,en);
  map.querySelector('[data-scene-node-role]').textContent=title(node,en,'role')||t('本節點名稱來自這項專題的課程資料；教材未另提供元件角色或設備型號。下列連結顯示它與其他節點的概念關係。','This node name comes from the project’s curriculum. No separate component role or equipment model was supplied. The connections below show its conceptual relationships.');
  const links=architecture.edges.filter(e=>e.from===id||e.to===id),holder=map.querySelector('[data-scene-node-links]');
  holder.innerHTML=links.length?links.map(edge=>{const other=architecture.nodes.find(n=>n.id===(edge.from===id?edge.to:edge.from));return `<button type="button" data-scene-node-jump="${esc(other.id)}">${edge.from===id?'→':'←'} ${esc(title(other,en))}${(en?edge.labelEn:edge.label)?' · '+esc(en?edge.labelEn:edge.label):''}</button>`;}).join(''):`<p>${t('此節點未提供連線。','No connections were supplied for this node.')}</p>`;
  holder.querySelectorAll('[data-scene-node-jump]').forEach(b=>on(b,'click',()=>selectProjectNode(b.dataset.sceneNodeJump)));
  const specific=node.sourceIds.length>0,ids=specific?node.sourceIds:architecture.sourceIds;map.querySelector('[data-scene-source-label]').textContent=specific?t('本節點來源','Node-specific sources'):t('本課程來源（未逐節點指定）','Course sources (not mapped to individual nodes)');
  map.querySelector('[data-scene-node-sources]').innerHTML=ids.length?ids.slice(0,6).map(id=>{const source=(options.sources||[]).find(s=>s.id===id),url=externalUrl(source?.url);return `<li>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title(source,en)||id)} ↗</a>`:esc(title(source,en)||id)}</li>`;}).join('')+(ids.length>6?`<li><a href="#project/${encodeURIComponent(course.id)}">${t('查看工程簡報的全部來源','View all sources in the project brief')} ↗</a></li>`:''):`<li>${t('此教材資料未附來源代碼；請查閱工程簡報。','No source IDs were supplied; consult the project brief.')}</li>`;
  drawArchitecture();options.onExplore?.({courseId:course.id,component:node.id,componentTitle:node.title,kind:architecture.kind});
 }
 if(map){map.querySelectorAll('[data-scene-node]').forEach(b=>on(b,'click',()=>selectProjectNode(b.dataset.sceneNode)));on(map,'toggle',drawArchitecture);selectProjectNode(architecture.nodes[0].id);}
 const detailText=result=>Object.entries(result.detail).map(([key,value])=>{const label={reactionDistance:pair('反應距離','Reaction distance'),brakingDistance:pair('煞車距離','Braking distance'),stoppingTime:pair('停車時間','Stopping time'),hydraulicPower:pair('水力輸入','Hydraulic input'),timeConstant:pair('時間常數','Time constant'),steadyRise:pair('穩態溫升','Steady rise'),current:pair('電流','Current'),transferTime:pair('傳輸時間','Transfer time'),computeTime:pair('計算時間','Compute time'),microstrain:pair('應變','Strain'),dragPower:pair('阻力功率','Drag power'),photonEnergyEv:pair('光子能量','Photon energy'),reynolds:pair('雷諾數','Reynolds number'),meanVelocity:pair('平均流速','Mean velocity'),energy:pair('熱量','Heat input')}[key]||[key,key],unit={reactionDistance:'m',brakingDistance:'m',stoppingTime:'s',hydraulicPower:'kW',timeConstant:'s',steadyRise:'K',current:'A',transferTime:'s',computeTime:'s',microstrain:'µε',dragPower:'W',photonEnergyEv:'eV',reynolds:'',meanVelocity:'m/s',energy:'J'}[key]||'';return text(label,en)+': '+number(value)+' '+unit;}).join(' · ');
 function updateModel(){const result=calculateSceneModel(kind,state.values);state.meterRatio=clamp((result.value-rangeMin)/Math.max(1e-10,rangeMax-rangeMin),0,1);fields.result.textContent=number(result.value)+' '+result.unit;fields.detail.textContent=detailText(result);for(const p of model.params)root.querySelector('[data-scene-output="'+p.id+'"]').textContent=number(state.values[p.id]);requestDraw();return result;}
 function requestDraw(){if(!state.destroyed&&visible&&!state.frame)state.frame=requestAnimationFrame(draw);}
 function draw(){state.frame=0;if(state.destroyed||!context)return;const {width,height}=state,dpr=Math.min(window.devicePixelRatio||1,2),camera=cameraFor(state.view,state.yaw,state.pitch,state.zoom,state.target);context.setTransform(dpr,0,0,dpr,0,0);context.clearRect(0,0,width,height);
  const faces=worldGeometry(model,state.view,state.selected,state.meterRatio).map(face=>{const points=face.points.map(p=>projectScenePoint(p,camera,width,height));return points.some(p=>!p)?null:{...face,projected:points,depth:points.reduce((s,p)=>s+p.depth,0)/points.length};}).filter(Boolean).sort((a,b)=>b.depth-a.depth);
  for(const face of faces){context.beginPath();face.projected.forEach((p,i)=>i?context.lineTo(p.x,p.y):context.moveTo(p.x,p.y));context.closePath();context.fillStyle=shade(face.colour,face.shade);context.globalAlpha=.93;context.fill();context.strokeStyle='rgba(8,25,35,.25)';context.lineWidth=.6;context.stroke();}context.globalAlpha=1;
  model.equipment.forEach(item=>{const button=root.querySelector('[data-scene-equipment="'+item.id+'"]'),p=projectScenePoint(add(item.position,[0,1.15,0]),camera,width,height);const show=p&&p.x>32&&p.x<width-32&&p.y>20&&p.y<height-40;button.hidden=!show;if(show){button.style.left=p.x+'px';button.style.top=p.y+'px';button.style.zIndex=String(Math.round(100-p.depth));}});
  photo.style.transform=`scale(1.06) translate(${Math.sin(state.yaw)*-1.5}%,${(state.pitch-.48)*2}%)`;
 }
 function resize(){const rect=viewport.getBoundingClientRect();if(rect.width<=0)return;state.width=rect.width;state.height=rect.height;const ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);canvas.style.width=rect.width+'px';canvas.style.height=rect.height+'px';drawArchitecture();requestDraw();}
 function setView(view){state.view=view;state.zoom=1;state.target=[0,.7,0];state.pitch=view==='first'?.1:view==='orbit'?.36:.48;root.querySelectorAll('[data-scene-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sceneView===view)));viewport.querySelector('.iv16-camera-tag').textContent=view==='first'?t('第一視角 · 從操作位置觀看','First person · operator viewpoint'):view==='orbit'?t('環繞視角 · 拖曳／縮放','Orbit view · drag / zoom'):t('第三視角 · 全景與學徒位置','Third person · overview and learner');requestDraw();}
 function select(id,focus=false){const item=model.equipment.find(x=>x.id===id);if(!item)return;state.selected=id;fields['equipment-title'].textContent=text(item.title,en);fields['equipment-body'].textContent=text(item.body,en);fields['equipment-check'].textContent=text(item.check,en);root.querySelectorAll('[data-scene-equipment], [data-scene-select]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.sceneEquipment||b.dataset.sceneSelect)===id)));const next=(model.equipment.indexOf(item)+1)%model.equipment.length;root.querySelector('[data-scene-tour]').textContent=t('下一台：','Next: ')+text(model.equipment[next].title,en);if(state.view==='first')state.target=[item.position[0]*.65,.8,item.position[2]*.65];requestDraw();if(focus){fields['equipment-title'].setAttribute('tabindex','-1');fields['equipment-title'].focus({preventScroll:true});}options.onExplore?.({courseId:course.id,equipment:id,kind});}
 root.querySelectorAll('[data-scene-equipment], [data-scene-select]').forEach(b=>on(b,'click',()=>select(b.dataset.sceneEquipment||b.dataset.sceneSelect)));
